    apply (lap_of_run tm Cc true true cho_1RB1RB_1LC0RB_0LC1RD_0LA1LA B0_1RB1RB_1LC0RB_0LC1RD_0LA1LA B1_1RB1RB_1LC0RB_0LC1RD_0LA1LA 2 12 p j' [] []).
