    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RB_1LC0RB_0LC1RD_0LA1LA p j' E).
    + exact (geo_1RB1RB_1LC0RB_0LC1RD_0LA1LA p j' E).
