Lemma fireo_1RB1RB_1LC0RB_0LC1RD_1LA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_1LC0RB_0LC1RD_1LA0LC = Some t ->
