Lemma geo_1RB1RB_1LC0RB_0LC1RD_1LA1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_1LC0RB_0LC1RD_1LA1RC) = lift (Cc (Pos.succ p)).
