  - destruct (lapi_1RB1RB_1LC0RB_0LC1RD_1LC1LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RB_1LC0RB_0LC1RD_1LC1LA B0_1RB1RB_1LC0RB_0LC1RD_1LC1LA B1_1RB1RB_1LC0RB_0LC1RD_1LC1LA 2 10 p j' [] []).
    + exact run_ovf_1RB1RB_1LC0RB_0LC1RD_1LC1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RB_1LC0RB_0LC1RD_1LC1LA p j' E).
    + exact (geo_1RB1RB_1LC0RB_0LC1RD_1LC1LA p j' E).
    + lia.
Qed.

