(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1RB_1LC0RB_0LC1RD_1LC1LA : existsb (fun tg => cfires tmm_1RB1RB_1LC0RB_0LC1RD_1LC1LA c0 7 tg) pins_1RB1RB_1LC0RB_0LC1RD_1LC1LA = true.
