    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RB_1LC0RD_0LC1LD_0RB1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_1LC0RD_0LC1LD_0RB1RA = Some t ->
