    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RB_1LC0RD_0LC1LD_0RB1RA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RB_1LC0RD_0LC1LD_0RB1RA
      with (l := [SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RB_1LC0RD_0LC1LD_0RB1RA
      with (l := [SWin 6; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RB_1LC0RD_0LC1LD_0RB1RA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RB_1LC0RD_0LC1LD_0RB1RA
      with (l := [SWin 5]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RB_1LC0RD_0LC1LD_0RB1RA
      with (l := [SWin 2]).
