Lemma lapi_1RB1RB_1RC1RC_1LD0RC_0LD1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (2 * j + 10). split; [lia|].
  rewrite (gsi_1RB1RB_1RC1RC_1LD0RC_0LD1LA p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1RB_1RC1RC_1LD0RC_0LD1LA A0_1RB1RB_1RC1RC_1LD0RC_0LD1LA A1_1RB1RB_1RC1RC_1LD0RC_0LD1LA 2 10
             run_int_1RB1RB_1RC1RC_1LD0RC_0LD1LA (Kp q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1RB_1RC1RC_1LD0RC_0LD1LA p j q0 E).
