Lemma gso_1RB1RB_1RC1RC_1LD0RC_0LD1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RB_1RC1RC_1LD0RC_0LD1LA.
Proof.
