  unfold Cc_1RB1RB_1RC1RC_1LD0RC_0LD1LA, cden, B0_1RB1RB_1RC1RC_1LD0RC_0LD1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RB_1RC1RC_1LD0RC_0LD1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RB_1RC1RC_1LD0RC_0LD1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_1RC1RC_1LD0RC_0LD1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RB_1RC1RC_1LD0RC_0LD1LA
             = (StC, (rep [S0] (S j) ++ [S1], S0, [S1;S1]))).
  { unfold cden, B1_1RB1RB_1RC1RC_1LD0RC_0LD1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0] (S j) ++ [S1]) ++ [S0], S0, [S1;S1]))).
  { unfold Cc_1RB1RB_1RC1RC_1LD0RC_0LD1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RB_1RC1RC_1LD0RC_0LD1LA. reflexivity.
