  - exact bootq_1RB1RB_1RC1RC_1LD0RC_0LD1LA.
  - intros p _. apply lap_1RB1RB_1RC1RC_1LD0RC_0LD1LA.
  - intros t Ht p _. apply fire_1RB1RB_1RC1RC_1LD0RC_0LD1LA. exact Ht.
  - exact wit_1RB1RB_1RC1RC_1LD0RC_0LD1LA.
  - apply qcleb_QC_28. reflexivity.
Qed.

Theorem qhtr_1RB1RB_1RC1RC_1LD0RC_0LD1LA : NonHalt tm_1RB1RB_1RC1RC_1LD0RC_0LD1LA /\ QHBoundTr 32779478 tm_1RB1RB_1RC1RC_1LD0RC_0LD1LA /\ QuasiHaltsTr tm_1RB1RB_1RC1RC_1LD0RC_0LD1LA.
