Lemma geo_1RB1RC_0LA0RC_1LD0RC_0LD1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RC_0LA0RC_1LD0RC_0LD1RB) = lift (Cc (Pos.succ p)).
