(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1RC_0LA0RC_1LD0RC_0LD1RB : existsb (fun tg => cfires tmm_1RB1RC_0LA0RC_1LD0RC_0LD1RB c0 9 tg) pins_1RB1RC_0LA0RC_1LD0RC_0LD1RB = true.
